    diffs = [b[i] - b[i-1] for i in range(1, n)]
    diff_count = {}

    for diff in diffs:
        if diff in diff_count:
            diff_count[diff] += 1
        else:
            diff_count[diff] = 1

    if len(diff_count) == 1:
        return -1

    most_common_diff = max(diff_count, key=diff_count.get)
    least_common_diff = min(diff_count, key=diff_count.get)

    if diff_count[most_common_diff] > 1:
        return -1

    for i in range(1, n):
        if b[i] - b[i-1] != most_common_diff:
            return i

    return -1

